class Palindrome:

    def __init__(self, string: str):
        self.string = string.lower()
        self.string = ''.join(e for e in self.string if e.isalnum())

    def is_palindrome(self) -> bool:
        return self.string == self.string[::-1]

    def _longest_palindromic_substring(self) -> str:
        res = ""
        for i in range(len(self.string)):
            # odd case
            tmp = self._helper(self.string, i, i)
            if len(tmp) > len(res):
                res = tmp
            # even case
            tmp = self._helper(self.string, i, i+1)
            if len(tmp) > len(res):
                res = tmp
        return res

    def _helper(self,s,l,r):
        while l >= 0 and r < len(s) and s[l] == s[r]:
            l -= 1
            r += 1
        return s[l+1:r]

    def make_palindrome(self) -> str:
