import java.util.*;

public class Solution {
    public int doAlgebra(List<String> operator, List<Integer> operand) {
        Stack<String> opStack = new Stack<String>();
        Stack<Integer> numStack = new Stack<Integer>();

        // Loop over each character
        for (int i = 0; i < operand.size(); i++) {

            // If the current character is a number, push it into numStack
            numStack.push(operand.get(i));

            // If the current character is an operator
            if (i < operator.size()) {
                while (!opStack.isEmpty() && getPrecedence(operator.get(i)) <= getPrecedence(opStack.peek())) {
                    numStack.push(calculate(opStack.pop(), numStack.pop(), numStack.pop()));
                }
                opStack.push(operator.get(i));
            }
        }

        // Finally, do the remaining operations
        while (!opStack.isEmpty()) {
            numStack.push(calculate(opStack.pop(), numStack.pop(), numStack.pop()));
        }

        return numStack.pop();
    }

    private int getPrecedence(String op) {
        switch (op) {
        case "+":
        case "-":
            return 1;
        case "*":
        case "/":
            return 2;
        case "**":
            return 3;
        default:
            return -1;
        }
    }

    private int calculate(String op, int num2, int num1) {
        switch (op) {
        case "+":
            return num1 + num2;
        case "-":
            return num1 - num2;
        case "*":
            return num1 * num2;
        case "/":
            return num1 / num2;
        case "**":
            return (int) Math.pow(num1, num2);
        default:
            return 0;
        }
    }
}

